// Command gen-cli-docs generates Markdown reference pages for all
// nwpc_data_client commands into the Sphinx documentation tree
// (default: ./docs/reference/cli). Run from the repository root:
//
//	go run ./tools/gen-cli-docs
//
// The generated files are committed to the repository (Read the Docs build
// jobs have no network access and cannot run Go). CI fails if they are out
// of date; regenerate with `make docs-cli` after changing any cobra command
// definition.
package main

import (
	"fmt"
	"os"

	"github.com/cemc-oper/nwpc-data-client/cmd"
	"github.com/spf13/cobra"
	"github.com/spf13/cobra/doc"
)

func main() {
	outputDir := "./docs/reference/cli"
	if len(os.Args) > 1 {
		outputDir = os.Args[1]
	}

	root := cmd.RootCommand()
	disableAutoGenTag(root)

	if err := os.MkdirAll(outputDir, 0o755); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	if err := doc.GenMarkdownTree(root, outputDir); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

// disableAutoGenTag drops the "Auto generated by spf13/cobra on <date>"
// footer so regenerated pages stay byte-identical between builds.
func disableAutoGenTag(c *cobra.Command) {
	c.DisableAutoGenTag = true
	for _, sub := range c.Commands() {
		disableAutoGenTag(sub)
	}
}
